const rows=[],raw=[];const assert=(value,label)=>{if(!value)throw Error(label)};
{
const store=new InMemoryCredentialStore(),credential={type:'api_key',key:'fixture-identity'},returned=await store.modify('a',async()=>credential),read=await store.read('a');const identity=returned===credential&&read===credential;const kept=await store.modify('a',async()=>undefined);assert(identity&&kept===credential,'credential identity');rows.push({name:'identity-and-undefined-retains',identity,retained:kept===credential,list:await store.list()});}
{
const store=new InMemoryCredentialStore(),events=[];let release,entered;const started=new Promise(r=>entered=r),gate=new Promise(r=>release=r);const first=store.modify('a',async()=>{events.push('first-enter');entered();await gate;events.push('first-exit');return{type:'api_key',key:'first'}});await started;const second=store.modify('a',async current=>{events.push('second-'+current.key);return{type:'api_key',key:'second'}});const other=await store.modify('b',async()=>{events.push('other');return{type:'api_key',key:'other'}});assert(other.key==='other'&&!events.some(x=>x.startsWith('second')),'independent key');release();await first;await second;rows.push({name:'serialize-one-key-independent-other',events,stored:await store.read('a')});}
{
const store=new InMemoryCredentialStore(),reason={fixture:'rejected'},events=[];try{await store.modify('a',async()=>{events.push('reject');throw reason});throw Error('missing reject')}catch(error){assert(error===reason,'reject identity')};const recovered=await store.modify('a',async current=>{events.push(current===undefined?'recover-empty':'wrong');return{type:'api_key',key:'recovered'}});rows.push({name:'rejected-tail-recovers',events,recovered});}
{
const store=new InMemoryCredentialStore(),events=[],controller=new AbortController(),reason={fixture:'cancel-wait'};let release,entered;const started=new Promise(r=>entered=r),gate=new Promise(r=>release=r);const first=store.modify('a',async()=>{events.push('first');entered();await gate;return{type:'api_key',key:'first'}});await started;const cancelled=store.modify('a',async()=>{events.push('cancelled-must-not-enter');return{type:'api_key',key:'cancelled'}},{signal:controller.signal});controller.abort(reason);let same=false;try{await cancelled}catch(error){same=error===reason}release();await first;const last=await store.modify('a',async current=>{events.push('last-'+current.key);return undefined});assert(same&&!events.includes('cancelled-must-not-enter'),'abort queued mutation');rows.push({name:'abort-wait-keeps-chain',same,events,last});}
{
const store=new InMemoryCredentialStore(),controller=new AbortController(),reason={fixture:'cancel-active'};let release,entered;const started=new Promise(r=>entered=r),gate=new Promise(r=>release=r);const pending=store.modify('a',async()=>{entered();await gate;return{type:'api_key',key:'must-not-publish'}},{signal:controller.signal});await started;controller.abort(reason);let same=false;try{await pending}catch(error){same=error===reason}release();await store.modify('a',async()=>undefined);const stored=await store.read('a');assert(same&&stored===undefined,'active cancellation publication');rows.push({name:'abort-active-checks-before-publication',same,storedType:typeof stored});}
{
const store=new InMemoryCredentialStore(),controller=new AbortController(),reason={fixture:'preabort'};controller.abort(reason);let reads=false,lists=false,mutates=false,deletes=false;for(const [name,call]of[['reads',()=>store.read('a',{signal:controller.signal})],['lists',()=>store.list({signal:controller.signal})],['mutates',()=>store.modify('a',async()=>{throw Error('unexpected')},{signal:controller.signal})],['deletes',()=>store.delete('a',{signal:controller.signal})]]){try{await call();throw Error('missing abort')}catch(error){assert(error===reason,name);if(name==='reads')reads=true;else if(name==='lists')lists=true;else if(name==='mutates')mutates=true;else deletes=true}}rows.push({name:'preaborted-operation-identities',reads,lists,mutates,deletes});}
raw.push(...rows);
